  /**
   * Initialize metrics queue for performance tracking
   */
  private initializeMetricsQueue(): void {
    try {
      const dbPath = `${process.env.HOME}/.openclaw/reasoning.db`;
      this.metricsQueue = createMetricsQueueWithDB(dbPath, {
        batchSize: 100,
        flushInterval: 5000, // 5 seconds
      });
      log.debug("Metrics queue initialized");
    } catch (error) {
      log.warn("Failed to initialize metrics queue:", error);
    }
  }

  /**
   * Initialize database schema for event persistence
   */
  private initializeDatabase(): void {
    try {
      this.db
        .prepare(`
        CREATE TABLE IF NOT EXISTS agent_events (
          id TEXT PRIMARY KEY,
          type TEXT NOT NULL,
          source TEXT NOT NULL,
          timestamp INTEGER NOT NULL,
          data TEXT NOT NULL,
          metadata TEXT DEFAULT '{}',
          created_at INTEGER DEFAULT (unixepoch())
        )
      `)
        .run();

      // Create index for faster queries
      this.db
        .prepare(`
        CREATE INDEX IF NOT EXISTS idx_agent_events_type 
        ON agent_events(type, timestamp)
      `)
        .run();

      this.db
        .prepare(`
        CREATE INDEX IF NOT EXISTS idx_agent_events_source 
        ON agent_events(source, timestamp)
      `)
        .run();


