- Opt-in with granular controls
- Differential privacy for aggregated patterns

### 2. **Efficient Incomplete Routine Detection**
```typescript
class RoutineDetector {
  private routineGraph: Map<string, RoutineNode[]> = new Map();

  async detectIncompleteRoutines(event: AgentEvent) {
    // Build routine sequences in real-time
    const sessionId = this.getCurrentSession(event);
    const routine = this.routineGraph.get(sessionId) || [];

    // Check against known patterns
    const matches = await this.findPatternMatches(routine);

    for (const match of matches) {
      if (this.isIncomplete(match, routine)) {
        const confidence = await this.calculateRoutineConfidence(match, routine);
        if (confidence >= this.getDynamicThreshold('routine')) {
          await this.suggestCompletion(match);
        }
      }
    }
  }
}
```

**Optimization Tricks:**
- Use Redis for ephemeral session storage (auto-expire)
- Store patterns as Bloom filters for fast matching
- Implement sliding window for routine detection

### 3. **Dynamic Confidence Thresholds**
```typescript
class AdaptiveThreshold {
  async calculateThreshold(suggestionType: string, context: ContextSnapshot): Promise<number> {
    const type = await this.getSuggestionType(suggestionType);
    let threshold = type.baseThreshold;

    // Adjust based on time of day (higher during quiet hours)
    if (this.isQuietHours(context.timestamp)) {
      threshold += 0.15;
    }

    // Adjust based on user state
    if (await this.isUserBusy(context)) {
      threshold += 0.1;
    }

    // Adjust based on recent accuracy
    const recentFeedback = this.feedbackHistory.get(suggestionType)?.slice(-10) || [];
    if (recentFeedback.length > 5) {
      const accuracy = recentFeedback.filter(f => f.positive).length / recentFeedback.length;
      threshold = threshold * (1 - (accuracy - 0.5) * 0.2);
    }

    return Math.max(0.6, Math.min(0.95, threshold));
  }
}
```

