} as const;

// Global registry for event mesh instances (for multi-agent scenarios)
export const globalEventMeshRegistry = new Map<string, AgentEventMesh>();

/**
 * Auto-Compaction
 *
 * Provides a simplified interface to trigger compaction from a sessionKey,
 * handling session lookup and parameter resolution internally.
 */

import type { OpenClawConfig } from "../config/config.js";
import { loadSessionStore, resolveSessionFilePath, resolveStorePath } from "../config/sessions.js";
import { createSubsystemLogger } from "../logging/subsystem.js";
import { isVerbose } from "../globals.js";
import { compactEmbeddedPiSession } from "./pi-embedded.js";

const log = createSubsystemLogger("auto-compaction");

/** Context required for auto-compaction */
export interface AutoCompactionContext {
  config: OpenClawConfig;
  workspaceDir: string;
}

let globalContext: AutoCompactionContext | null = null;

/**
 * Initialize the auto-compaction context.
 * Must be called at startup before any auto-compaction can be triggered.
 */
export function initAutoCompactionContext(ctx: AutoCompactionContext): void {
  globalContext = ctx;
  log.debug("Auto-compaction context initialized");
}

/**
 * Trigger auto-compaction for a session.
 * Uses the global context to resolve session info and trigger compaction.
 */
export async function triggerAutoCompaction(
  sessionKey: string,
  agentId: string,
): Promise<{ ok: boolean; reason?: string }> {
  if (!globalContext) {
    log.warn("Auto-compaction context not initialized");
    return { ok: false, reason: "context not initialized" };
  }

  const { config, workspaceDir } = globalContext;

  try {
    // Resolve session store path for this agent
    const storePath = resolveStorePath(config?.session?.store, { agentId });

    // Load session store and find the entry
    const store = loadSessionStore(storePath);
    const sessionEntry = store[sessionKey];

    if (!sessionEntry?.sessionId) {
      log.warn(`Session not found for key: ${sessionKey}`);
      return { ok: false, reason: "session not found" };
    }

    const sessionId = sessionEntry.sessionId;
    const sessionFile = resolveSessionFilePath(sessionId, sessionEntry, { agentId });

    if (isVerbose()) {
      log.info(`Triggering auto-compaction for session ${sessionKey}`);
    }

    // Trigger compaction with minimal required parameters
    const result = await compactEmbeddedPiSession({
      sessionId,
      sessionKey,
      sessionFile,
      workspaceDir,
      config,
      groupId: sessionEntry.groupId,
      groupChannel: sessionEntry.groupChannel,
      groupSpace: sessionEntry.space,
      spawnedBy: sessionEntry.spawnedBy,
      skillsSnapshot: sessionEntry.skillsSnapshot,
      customInstructions: "Auto-compaction triggered after 25 answers.",
    });

    if (result.ok) {
      log.info(
        `Auto-compaction completed for ${sessionKey}: ${result.compacted ? "compacted" : "skipped"}`,
      );
      return { ok: true, reason: result.reason };
    } else {
      log.error(`Auto-compaction failed for ${sessionKey}: ${result.reason}`);
      return { ok: false, reason: result.reason };
    }
  } catch (error) {
    const errMsg = error instanceof Error ? error.message : String(error);
    log.error(`Auto-compaction error for ${sessionKey}: ${errMsg}`);
    return { ok: false, reason: errMsg };
  }
}

/**
 * Answer Briefing Tracker
 *
 * Tracks agent answers per session and:
 * 1. Records briefing after EVERY answer
 * 2. Triggers auto-compact after 25 answers
 *
 * Listens for "answer" stream events emitted when assistant messages complete.
 */

import { promises as fs } from "fs";
import path from "path";
import { onAgentEvent, type AgentEventPayload } from "../infra/agent-events.js";
import { createSubsystemLogger } from "../logging/subsystem.js";
import { isVerbose } from "../globals.js";
import {
  recordCompaction,
  type CompactionBriefingConfig,
  type CompactionEvent,
} from "./compaction-briefing.js";
import { extractAgentIdFromSessionKey } from "./session-utils.js";

const log = createSubsystemLogger("answer-briefing-tracker");

/** Configuration for the answer briefing tracker */
export interface AnswerBriefingConfig extends CompactionBriefingConfig {
  /** Number of answers before triggering auto-compact (default: 25) */
  compactAfterAnswers?: number;
  /** Number of cycles before aggregating into master briefing (default: 2) */
  aggregateAfterCycles?: number;
  /** Callback to trigger compaction */
  onCompactNeeded?: (sessionKey: string, agentId: string) => Promise<void>;
  /** LLM config for cycle summaries */
  llmConfig?: {
    apiKey: string;
    model?: string;
    baseUrl?: string;
  };
}

const DEFAULT_COMPACT_AFTER_ANSWERS = 40;
const DEFAULT_AGGREGATE_AFTER_CYCLES = 3;

// Track answer counts by sessionKey
const answerCounts = new Map<
  string,
  {
    count: number;
    agentId: string;
    answerTexts: string[]; // Collect all answer texts for cycle summary
  }
>();

// Collect cycle summaries for aggregation (NOT saved to context)
const cycleSummaries: string[] = [];
let cycleCount = 0;

// Keep recent summaries for continuity (last 2 cycles)
let recentSummaries: string[] = [];

/** Get recent summaries for context continuity */
export function getRecentSummaries(): string[] {
  return recentSummaries;
}

let unsubscribe: (() => void) | null = null;
let config: AnswerBriefingConfig = {};

/**
 * Initialize the answer briefing tracker
 */
export function initAnswerBriefingTracker(cfg?: AnswerBriefingConfig): void {
  if (unsubscribe) {
    log.debug("Answer briefing tracker already initialized");
    return;
  }

  config = cfg || {};

  unsubscribe = onAgentEvent(handleAgentEvent);
  log.info("Answer briefing tracker initialized");
}

/**
 * Stop the answer briefing tracker
 */
export function stopAnswerBriefingTracker(): void {
  if (unsubscribe) {
    unsubscribe();
    unsubscribe = null;
    answerCounts.clear();
    log.info("Answer briefing tracker stopped");
  }
}

/**
 * Handle agent events
 */
function handleAgentEvent(evt: AgentEventPayload): void {
  // Listen for "answer" stream events (emitted when assistant message completes)
  if (evt.stream !== "answer") {
    return;
  }

  const sessionKey = evt.sessionKey || evt.runId;
  const answerText = (evt.data?.text as string) || "";

  if (!answerText.trim()) {
    return;
  }

  const agentId = extractAgentIdFromSessionKey(sessionKey);

  // Get or create answer tracking for this session
  let tracker = answerCounts.get(sessionKey);
  if (!tracker) {
    tracker = {
      count: 0,
      agentId,
      answerTexts: [],
    };
    answerCounts.set(sessionKey, tracker);
  }

  // Increment answer count
  tracker.count += 1;
  tracker.answerTexts.push(answerText.slice(0, 300)); // Collect for cycle summary

  log.debug(`Answer #${tracker.count} for session ${sessionKey}`);

  // Record briefing for this answer
  void recordAnswerBriefing(sessionKey, agentId, tracker.count, answerText);

  // Check if we need to trigger auto-compact
  const compactAfter = config.compactAfterAnswers || DEFAULT_COMPACT_AFTER_ANSWERS;
  if (tracker.count >= compactAfter) {
    if (isVerbose()) {
      log.info(`Session ${sessionKey} reached ${tracker.count} answers, triggering auto-compact`);
    }

    // Generate cycle summary before resetting
    const cycleTexts = [...tracker.answerTexts];

    // Reset counter
    tracker.count = 0;
    tracker.answerTexts = [];

    // Generate cycle summary (collected, not saved to context)
    void generateAndCollectCycleSummary(cycleTexts, sessionKey);

    // Trigger compaction
    if (config.onCompactNeeded) {
      void config.onCompactNeeded(sessionKey, agentId).catch((err) => {
        log.error(`Failed to trigger compaction for ${sessionKey}: ${err}`);
      });
    }
  }
}

/**
 * Record a briefing entry for an answer
 */
async function recordAnswerBriefing(
  sessionKey: string,
  agentId: string,
  answerNumber: number,
  answerText: string,
): Promise<void> {
  try {
    const compactionEvent: CompactionEvent = {
      sessionKey,
      agentId,
      timestamp: Date.now(),
      tokensBefore: 0,
      tokensAfter: 0,
      messagesCompacted: 0,
      summary: `Answer #${answerNumber}`,
    };

    // Generate a summary of the answer (optimized: shorter summaries)
    const summary = `Answer #${answerNumber}: ${answerText.slice(0, 150).trim()}${answerText.length > 150 ? "..." : ""}`;

    await recordCompaction(compactionEvent, summary, config);
    log.debug(`Recorded briefing for answer #${answerNumber} in session ${sessionKey}`);
  } catch (error) {
    log.error(`Failed to record answer briefing: ${error}`);
  }
}

/**
 * Get the current answer count for a session
 */
export function getAnswerCount(sessionKey: string): number {
  return answerCounts.get(sessionKey)?.count || 0;
}

/**
 * Reset the answer count for a session
 */
export function resetAnswerCount(sessionKey: string): void {
  const tracker = answerCounts.get(sessionKey);
  if (tracker) {
    tracker.count = 0;
  }
}

/**
 * Update the configuration
 */
export function updateAnswerBriefingConfig(cfg: AnswerBriefingConfig): void {
  config = { ...config, ...cfg };
}

/**
 * Generate a cycle summary and collect it (NOT saved to context)
 */
async function generateAndCollectCycleSummary(
  answerTexts: string[],
  sessionKey: string,
): Promise<void> {
  if (!config.llmConfig?.apiKey) {
    log.debug("No LLM config for cycle summary, skipping");
    return;
  }

  const model = config.llmConfig.model || "google/gemini-2.5-flash";
  const baseUrl = config.llmConfig.baseUrl || "https://openrouter.ai/api/v1";

  const prompt = `Summarize this conversation cycle into 2-3 concise bullet points. Focus on key decisions and action items only.

Conversation excerpts:
${answerTexts.map((t, i) => `${i + 1}. ${t}`).join("\n")}

Provide a brief summary (max 60 words).`;

  try {
    const response = await fetch(`${baseUrl}/chat/completions`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${config.llmConfig.apiKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model,
        messages: [{ role: "user", content: prompt }],
        max_tokens: 150,
      }),
    });

    if (!response.ok) {
      throw new Error(`LLM API error: ${response.status}`);
    }

    const data = await response.json();
    const summary = data.choices?.[0]?.message?.content || "Cycle summary unavailable.";

    // Collect for aggregation
    cycleSummaries.push(summary);
    cycleCount++;

    // Keep recent summaries for context continuity (last 2 cycles)
    recentSummaries.push(summary);
    if (recentSummaries.length > 2) {
      recentSummaries.shift(); // Keep only last 2
    }

    // Update RECENT_CONTEXT.md for next session
    await updateRecentContext();

    log.info(
      `Cycle #${cycleCount} summary collected (${cycleSummaries.length} total, ${recentSummaries.length} recent)`,
    );

    // Check if we should aggregate and save
    const aggregateAfter = config.aggregateAfterCycles || DEFAULT_AGGREGATE_AFTER_CYCLES;
    if (cycleCount >= aggregateAfter) {
      await aggregateAndSaveBriefing();
    }
  } catch (error) {
    log.error(`Failed to generate cycle summary: ${error}`);
  }
}

/**
 * Aggregate all cycle summaries into one master briefing and save
 */
async function aggregateAndSaveBriefing(): Promise<void> {
  if (cycleSummaries.length === 0) {
    log.debug("No cycle summaries to aggregate");
    return;
  }

  if (!config.llmConfig?.apiKey) {
    log.debug("No LLM config for aggregation, dumping raw summaries");
    await writeBriefingFile(cycleSummaries.join("\n\n"));
    cycleSummaries.length = 0;
    cycleCount = 0;
    return;
  }

  const model = config.llmConfig.model || "google/gemini-2.5-flash";
  const baseUrl = config.llmConfig.baseUrl || "https://openrouter.ai/api/v1";

  const prompt = `You are summarizing ${cycleSummaries.length} conversation cycles. Create ONE cohesive briefing (3-5 bullet points) covering:

1. Main topics discussed
2. Key decisions made
3. Important action items

Cycle summaries:
${cycleSummaries.map((s, i) => `--- Cycle ${i + 1} ---\n${s}`).join("\n")}

Create a concise master briefing (max 100 words).`;

  try {
    const response = await fetch(`${baseUrl}/chat/completions`, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${config.llmConfig.apiKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model,
        messages: [{ role: "user", content: prompt }],
        max_tokens: 200,
      }),
    });

    if (!response.ok) {
      throw new Error(`LLM API error: ${response.status}`);
    }

    const data = await response.json();
    const masterBriefing = data.choices?.[0]?.message?.content || cycleSummaries.join("\n\n");

    // Write the aggregated briefing
    await writeBriefingFile(masterBriefing);

    log.info(`Aggregated briefing saved (${cycleSummaries.length} cycles → 1 briefing)`);

    // Clear collected summaries (tokens saved!)
    cycleSummaries.length = 0;
    cycleCount = 0;
  } catch (error) {
    log.error(`Failed to aggregate briefing: ${error}`);
    // Fallback: write raw summaries
    await writeBriefingFile(cycleSummaries.join("\n\n"));
    cycleSummaries.length = 0;
    cycleCount = 0;
  }
}

/**
 * Write briefing to briefings/YYYY-MM-DD.md (OUTSIDE memory/ to avoid token burn)
 */
async function writeBriefingFile(content: string): Promise<void> {
  const now = new Date();
  const dateStr = now.toISOString().split("T")[0];
  const timeStr = now.toTimeString().slice(0, 5);

  // Write to briefings/ folder (NOT memory/briefings/ - avoid auto-indexing)
  const workspacePath =
    process.env.OPENCLAW_WORKSPACE || path.join(process.env.HOME || "", ".openclaw", "workspace");
  const briefingDir = path.join(workspacePath, "briefings");
  const briefingPath = path.join(briefingDir, `${dateStr}.md`);

  try {
    // Ensure directory exists
    await fs.mkdir(briefingDir, { recursive: true });

    // Append master briefing entry
    const entry = `\n## Aggregated Briefing (${timeStr})\n${content}\n`;
    await fs.appendFile(briefingPath, entry, "utf-8");

    log.debug(`Wrote aggregated briefing to ${briefingPath}`);
  } catch (error) {
    log.error(`Failed to write briefing file: ${error}`);
  }
}

/**
 * Update RECENT_CONTEXT.md with latest summaries (for continuity)
 */
async function updateRecentContext(): Promise<void> {
  if (recentSummaries.length === 0) return;

  const workspacePath =
    process.env.OPENCLAW_WORKSPACE || path.join(process.env.HOME || "", ".openclaw", "workspace");
  const contextPath = path.join(workspacePath, "RECENT_CONTEXT.md");

  const content = `# Recent Context

Last ${recentSummaries.length} conversation cycles:

${recentSummaries.map((s, i) => `## Cycle ${i + 1}\n${s}`).join("\n\n")}

---
*Auto-updated. Do not edit manually.*
`;

  try {
    await fs.writeFile(contextPath, content, "utf-8");
    log.debug(`Updated RECENT_CONTEXT.md with ${recentSummaries.length} summaries`);
  } catch (error) {
    log.error(`Failed to update RECENT_CONTEXT.md: ${error}`);
  }
}

/**
 * Force aggregation (e.g., at end of day)
 */
export async function forceAggregateBriefing(): Promise<void> {
  if (cycleSummaries.length > 0) {
    await aggregateAndSaveBriefing();
  }
}

/**
 * Get current cycle stats
 */
export function getCycleStats(): { cycleCount: number; summariesCollected: number } {
  return { cycleCount, summariesCollected: cycleSummaries.length };
}

/**
 * Tool Execution Wrapper with Hooks Integration
 *
 * Wraps tool execution with hook support, allowing hooks to:
 * - Block/modify tool execution (PreToolUse)
 * - Process tool results (PostToolUse)
 * - Handle tool failures (PostToolUseFailure)
 *
 * Also includes Plan Mode blocking and AcceptEdits permission checking.
 * Works with ANY LLM provider (client-side feature).
 */

import type { HookExecutionResult } from "../hooks/executor.js";
import type { AnyAgentTool } from "./tools/common.js";
import { globalHookExecutor } from "../hooks/executor.js";
import {
  shouldBlockToolExecution,
  getToolBlockReason,
  getPermissionMode,
  setPermissionMode,
  shouldPromptForTool,
  getToolPermissionDecision,
  getToolCategory,
  PERMISSION_MODE_DESCRIPTIONS,
} from "./plan-mode/permission-mode.js";
import { isYoloModeActive } from "./yolo-mode/index.js";
import { getFileHistoryManager } from "./file-history/index.js";
import { createSubsystemLogger } from "../logging/subsystem.js";

const log = createSubsystemLogger("tool-execution");

/**
 * Tool execution result
 */
export interface ToolExecutionResult {
  blocked: boolean;
  reason?: string;
  systemMessage?: string;
  result?: unknown;
  updatedInput?: Record<string, unknown>;
  additionalContext?: string;
  /** Current permission mode */
  permissionMode?: string;
  /** Whether this tool would normally require approval (for gateway mode) */
  needsApproval?: boolean;
  /** Tool category for display */
  toolCategory?: "edit" | "destructive" | "readonly" | "unknown";
  /** Permission decision for this tool */
  permissionDecision?: "auto-approve" | "prompt" | "block";
}

/**
 * Get permission info for a tool (for gateway mode)
 * Returns metadata about whether the tool needs approval
 */
export function getToolPermissionInfo(toolName: string): {
  toolCategory: "edit" | "destructive" | "readonly" | "unknown";
  permissionDecision: "auto-approve" | "prompt" | "block";
  needsApproval: boolean;
  permissionMode: string;
} {
  const category = getToolCategory(toolName);
  const decision = getToolPermissionDecision(toolName);
  const mode = getPermissionMode();

  return {
    toolCategory: category,
    permissionDecision: decision,
    needsApproval: decision === "prompt",
    permissionMode: mode,
  };
}

/**
 * Check if a tool should be auto-approved in current mode
 * Useful for gateway to skip approval UI
 */
export function isToolAutoApprovedInCurrentMode(toolName: string): boolean {
  return getToolPermissionDecision(toolName) === "auto-approve";
}

/**
 * Execute tool with hooks integration
 *
 * @param tool - Tool to execute
 * @param args - Tool arguments
 * @param context - Execution context
 * @returns Tool execution result
 */
export async function executeToolWithHooks(
  tool: AnyAgentTool,
  args: Record<string, unknown>,
  context: {
    session_id: string;
    tool_use_id: string;
    cwd: string;
    transcript_path?: string;
    permission_mode?: string;
  },
): Promise<ToolExecutionResult> {
  // YOLO mode check - bypasses all permission checks
  if (isYoloModeActive()) {
    // In YOLO mode, skip plan mode blocking
    // Only hook blocking still applies
  } else {
    // ADD: Check plan mode blocking FIRST (before hooks)
    const planModeBlock = shouldBlockToolExecution(tool.name);
    if (planModeBlock) {
      return {
        blocked: true,
        reason: getToolBlockReason(tool.name),
        permissionMode: getPermissionMode(),
      };
    }
  }

  // Build base context for hooks
  const baseContext = {
    session_id: context.session_id,
    transcript_path: context.transcript_path || "",
    cwd: context.cwd,
    permission_mode: context.permission_mode || getPermissionMode(),
    tool_name: tool.name,
    tool_use_id: context.tool_use_id,
  };

  // ========================================
  // PRE TOOL USE HOOKS
  // ========================================
  const preToolUseResult = await globalHookExecutor.executeHooks("PreToolUse", {
    ...baseContext,
    hook_event_name: "PreToolUse",
    tool_input: args,
  });

  // Handle hook decisions
  if (preToolUseResult.preventContinuation) {
    return {
      blocked: true,
      reason: preToolUseResult.stopReason || "Blocked by hook",
      systemMessage: preToolUseResult.systemMessage,
    };
  }

  // Handle permission behavior
  if (preToolUseResult.permissionBehavior === "deny") {
    return {
      blocked: true,
      reason: preToolUseResult.blockingError?.blockingError || "Denied by hook",
      systemMessage: preToolUseResult.systemMessage,
    };
  }

  // Use modified input if provided
  const finalArgs = preToolUseResult.updatedInput || args;

  // ========================================
  // CREATE FILE SNAPSHOT (before edit tools)
  // ========================================
  let snapshotId: string | undefined;
  const editTools = ["edit", "write", "notebookedit", "notebook_write"];
  const isEditTool = editTools.some((t) => tool.name.toLowerCase().includes(t));

  if (isEditTool) {
    try {
      const fileHistoryManager = getFileHistoryManager(context.cwd);
      // Track file if path provided
      const filePath = (finalArgs as any).path || (finalArgs as any).file_path;
      if (filePath) {
        fileHistoryManager.trackFile(filePath);
      }

      // Create snapshot before edit
      const snapshot = await fileHistoryManager.createSnapshot(context.tool_use_id, {
        description: `Before ${tool.name} tool execution`,
      });
      if (snapshot) {
        snapshotId = snapshot.id;
      }
    } catch (error) {
      log.debug(`Failed to create file snapshot: ${error}`);
      // Continue even if snapshot fails
    }
  }

  // ========================================
  // EXECUTE TOOL
  // ========================================
  let result: unknown;
  let error: Error | null = null;

  try {
    result = await tool.call(finalArgs, {
      abortController: new AbortController(),
      getAppState: async () => ({}),
    });
  } catch (e) {
    error = e instanceof Error ? e : new Error(String(e));
  }

  // ========================================
  // POST TOOL USE / FAILURE HOOKS
  // ========================================
  if (error) {
    // Tool failed - run PostToolUseFailure hooks
    const postFailureResult = await globalHookExecutor.executeHooks("PostToolUseFailure", {
      ...baseContext,
      hook_event_name: "PostToolUseFailure",
      tool_input: finalArgs,
      error: error.message,
      is_interrupt: false,
    });

    // Add additional context from hooks
    let errorMessage = error.message;
    if (postFailureResult.additionalContext) {
      errorMessage = `${errorMessage}\n\nHook context: ${postFailureResult.additionalContext}`;
    }

    throw new Error(errorMessage);
  } else {
    // Process result with EloClaw tool persistence
    let finalResult = result;

    // Check if result should be persisted (>100KB)
    const resultSize = typeof result === 'string' ? result.length : 
      Array.isArray(result) ? JSON.stringify(result).length : 0;

    if (resultSize > 100_000) { // 100KB threshold
      try {
        const { processToolResult } = await import('./tools/tool-result-persist.js');
        const persistResult = await processToolResult(result, {
          toolUseId: context.tool_use_id,
          toolName: tool.name,
          maxSizeChars: 100_000,
          previewSizeChars: 10_000
        });

        if (persistResult.persisted) {
          finalResult = persistResult.content;
          log.info(`Persisted large tool result: ${persistResult.telemetry?.estimatedOriginalTokens} → ${persistResult.telemetry?.estimatedPersistedTokens} tokens`);
        }
      } catch (persistError) {
        log.warn(`Tool result persistence failed, using original: ${persistError}`);
      }
    }

    // Tool succeeded - run PostToolUse hooks
    const postToolUseResult = await globalHookExecutor.executeHooks("PostToolUse", {
      ...baseContext,
      hook_event_name: "PostToolUse",
      tool_input: finalArgs,
      tool_response: finalResult, // Use potentially persisted result
    });

    // Use modified tool output if provided
    if (postToolUseResult.updatedMCPToolOutput) {
      finalResult = postToolUseResult.updatedMCPToolOutput;
    }

    // Build return value
    const returnValue: ToolExecutionResult = {
      blocked: false,
      result: finalResult,
      snapshotId,
    };

    // Add additional context
    if (postToolUseResult.additionalContext) {
      returnValue.additionalContext = postToolUseResult.additionalContext;
    }

    // Add system message
    if (postToolUseResult.systemMessage) {
      returnValue.systemMessage = postToolUseResult.systemMessage;
    }

    return returnValue;
  }
}

/**
 * Check if hooks are registered for tool events
 */
export function hasToolHooks(toolName: string): boolean {
  return (
    globalHookExecutor.hasHooks("PreToolUse") ||
    globalHookExecutor.hasHooks("PostToolUse") ||
    globalHookExecutor.hasHooks("PostToolUseFailure")
  );
}

/**
 * Get hook count for tool events
 */
export function getToolHookCount(toolName: string): number {
  return (
    globalHookExecutor.getHookCount("PreToolUse") +
    globalHookExecutor.getHookCount("PostToolUse") +
    globalHookExecutor.getHookCount("PostToolUseFailure")
  );
}

/**
 * OpenClaw Streaming Tool Execution
 *
 * Enables streaming tool execution with real-time output.
 * Works with SSE server for token-by-token display.
 */

import type { SSEServer } from "../streaming/sse-server.js";
import type { AnyAgentTool } from "./tools/common.js";

/**
 * Execute tool with streaming output
 */
export async function executeToolWithStreaming(
  tool: AnyAgentTool,
  args: Record<string, unknown>,
  sessionKey: string,
  sse: SSEServer,
): Promise<unknown> {
  const toolId = `tool_${Date.now()}_${Math.random().toString(36).slice(2)}`;

  // Send tool start event
  sse.sendToolEvent(tool.name, toolId, "starting");

  try {
    // Execute tool
    const result = await tool.call(args, {
      abortController: new AbortController(),
      getAppState: async () => ({}),
    });

    // Send tool complete event
    sse.sendToolEvent(tool.name, toolId, "complete", JSON.stringify(result));

    return result;
  } catch (error) {
    // Send tool error event
    sse.sendToolEvent(tool.name, toolId, "error", undefined, (error as Error).message);
    throw error;
  }
}

/**
 * Stream tool output chunk by chunk
 */
export async function streamToolOutput(
  tool: AnyAgentTool,
  args: Record<string, unknown>,
  sse: SSEServer,
  chunkSize: number = 10,
): Promise<unknown> {
  const toolId = `tool_${Date.now()}_${Math.random().toString(36).slice(2)}`;

  // Send tool start event
  sse.sendToolEvent(tool.name, toolId, "starting");

  try {
    // Execute tool
    const result = await tool.call(args, {
      abortController: new AbortController(),
      getAppState: async () => ({}),
    });

    // Stream result as chunks
    const resultStr = JSON.stringify(result);

    for (let i = 0; i < resultStr.length; i += chunkSize) {
      const chunk = resultStr.slice(i, i + chunkSize);
      sse.sendToolEvent(tool.name, toolId, "running", chunk);

      // Small delay for streaming effect
      await new Promise((resolve) => setTimeout(resolve, 10));
    }

    // Send tool complete event
    sse.sendToolEvent(tool.name, toolId, "complete");

    return result;
  } catch (error) {
    // Send tool error event
    sse.sendToolEvent(tool.name, toolId, "error", undefined, (error as Error).message);
    throw error;
  }
}

import type { AgentEvent } from "@mariozechner/pi-agent-core";
import type { EmbeddedPiSubscribeContext } from "./pi-embedded-subscribe.handlers.types.js";
import { emitAgentEvent } from "../infra/agent-events.js";
import { normalizeTextForComparison } from "./pi-embedded-helpers.js";
import { isMessagingTool, isMessagingToolSendAction } from "./pi-embedded-messaging.js";
import {
  extractToolErrorMessage,
  extractToolResultText,
  extractMessagingToolSend,
  isToolResultError,
  sanitizeToolResult,
} from "./pi-embedded-subscribe.tools.js";
import { inferToolMetaFromArgs } from "./pi-embedded-utils.js";
import {
  getOlapAnalytics,
  publishEvent,
  updatePredictiveContext,
} from "./predictive-integration.js";
import { normalizeToolName } from "./tool-policy.js";

function extendExecMeta(toolName: string, args: unknown, meta?: string): string | undefined {
  const normalized = toolName.trim().toLowerCase();
  if (normalized !== "exec" && normalized !== "bash") {
    return meta;
  }
  if (!args || typeof args !== "object") {
    return meta;
  }
  const record = args as Record<string, unknown>;
  const flags: string[] = [];
  if (record.pty === true) {
    flags.push("pty");
  }
  if (record.elevated === true) {
    flags.push("elevated");
  }
  if (flags.length === 0) {
    return meta;
  }
  const suffix = flags.join(" · ");
  return meta ? `${meta} · ${suffix}` : suffix;
}

export async function handleToolExecutionStart(
  ctx: EmbeddedPiSubscribeContext,
  evt: AgentEvent & { toolName: string; toolCallId: string; args: unknown },
) {
  // Flush pending block replies to preserve message boundaries before tool execution.
  ctx.flushBlockReplyBuffer();
  if (ctx.params.onBlockReplyFlush) {
    void ctx.params.onBlockReplyFlush();
  }

  const rawToolName = String(evt.toolName);
  const toolName = normalizeToolName(rawToolName);
  const toolCallId = String(evt.toolCallId);
  const args = evt.args;

  if (toolName === "read") {
    const record = args && typeof args === "object" ? (args as Record<string, unknown>) : {};
    const filePath = typeof record.path === "string" ? record.path.trim() : "";
    if (!filePath) {
      const argsPreview = typeof args === "string" ? args.slice(0, 200) : undefined;
      ctx.log.warn(
        `read tool called without path: toolCallId=${toolCallId} argsType=${typeof args}${argsPreview ? ` argsPreview=${argsPreview}` : ""}`,
      );
    }
  }

  const meta = extendExecMeta(toolName, args, inferToolMetaFromArgs(toolName, args));
  ctx.state.toolMetaById.set(toolCallId, meta);
  ctx.state.toolStartTimes.set(toolCallId, Date.now());
  ctx.log.debug(
    `embedded run tool start: runId=${ctx.params.runId} tool=${toolName} toolCallId=${toolCallId}`,
  );

  const shouldEmitToolEvents = ctx.shouldEmitToolResult();
  emitAgentEvent({
    runId: ctx.params.runId,
    stream: "tool",
    data: {
      phase: "start",
      name: toolName,
      toolCallId,
      args: args as Record<string, unknown>,
    },
  });
  // Best-effort typing signal; do not block tool summaries on slow emitters.
  void ctx.params.onAgentEvent?.({
    stream: "tool",
    data: { phase: "start", name: toolName, toolCallId },
  });

  if (
    ctx.params.onToolResult &&
    shouldEmitToolEvents &&
    !ctx.state.toolSummaryById.has(toolCallId)
  ) {
    ctx.state.toolSummaryById.add(toolCallId);
    ctx.emitToolSummary(toolName, meta);
  }

  // Track messaging tool sends (pending until confirmed in tool_execution_end).
  if (isMessagingTool(toolName)) {
    const argsRecord = args && typeof args === "object" ? (args as Record<string, unknown>) : {};
    const isMessagingSend = isMessagingToolSendAction(toolName, argsRecord);
    if (isMessagingSend) {
      const sendTarget = extractMessagingToolSend(toolName, argsRecord);
      if (sendTarget) {
        ctx.state.pendingMessagingTargets.set(toolCallId, sendTarget);
      }
      // Field names vary by tool: Discord/Slack use "content", sessions_send uses "message"
      const text = (argsRecord.content as string) ?? (argsRecord.message as string);
      if (text && typeof text === "string") {
        ctx.state.pendingMessagingTexts.set(toolCallId, text);
        ctx.log.debug(`Tracking pending messaging text: tool=${toolName} len=${text.length}`);
      }
    }
  }
}

export function handleToolExecutionUpdate(
  ctx: EmbeddedPiSubscribeContext,
  evt: AgentEvent & {
    toolName: string;
    toolCallId: string;
    partialResult?: unknown;
  },
) {
  const toolName = normalizeToolName(String(evt.toolName));
  const toolCallId = String(evt.toolCallId);
  const partial = evt.partialResult;
  const sanitized = sanitizeToolResult(partial);
  emitAgentEvent({
    runId: ctx.params.runId,
    stream: "tool",
    data: {
      phase: "update",
      name: toolName,
      toolCallId,
      partialResult: sanitized,
    },
  });
  void ctx.params.onAgentEvent?.({
    stream: "tool",
    data: {
      phase: "update",
      name: toolName,
      toolCallId,
    },
  });
}

export function handleToolExecutionEnd(
  ctx: EmbeddedPiSubscribeContext,
  evt: AgentEvent & {
    toolName: string;
    toolCallId: string;
    isError: boolean;
    result?: unknown;
  },
) {
  const toolName = normalizeToolName(String(evt.toolName));
  const toolCallId = String(evt.toolCallId);
  const isError = Boolean(evt.isError);
  const result = evt.result;
  const isToolError = isError || isToolResultError(result);
  const sanitizedResult = sanitizeToolResult(result);
  const meta = ctx.state.toolMetaById.get(toolCallId);
  ctx.state.toolMetas.push({ toolName, meta });
  ctx.state.toolMetaById.delete(toolCallId);
  ctx.state.toolSummaryById.delete(toolCallId);
  if (isToolError) {
    const errorMessage = extractToolErrorMessage(sanitizedResult);
    ctx.state.lastToolError = {
      toolName,
      meta,
      error: errorMessage,
    };
  }

  // Commit messaging tool text on success, discard on error.
  const pendingText = ctx.state.pendingMessagingTexts.get(toolCallId);
  const pendingTarget = ctx.state.pendingMessagingTargets.get(toolCallId);
  if (pendingText) {
    ctx.state.pendingMessagingTexts.delete(toolCallId);
    if (!isToolError) {
      ctx.state.messagingToolSentTexts.push(pendingText);
      ctx.state.messagingToolSentTextsNormalized.push(normalizeTextForComparison(pendingText));
      ctx.log.debug(`Committed messaging text: tool=${toolName} len=${pendingText.length}`);
      ctx.trimMessagingToolSent();
    }
  }
  if (pendingTarget) {
    ctx.state.pendingMessagingTargets.delete(toolCallId);
    if (!isToolError) {
      ctx.state.messagingToolSentTargets.push(pendingTarget);
      ctx.trimMessagingToolSent();
    }
  }

