// Execute single tool
export async function executeToolWithHooks(
  tool: AnyAgentTool,
  args: Record<string, unknown>,
  context: { session_id: string; ... }
): Promise<ToolExecutionResult> {
  // Plan mode check
  if (shouldBlockToolExecution(tool.name)) { ... }

  // Hooks processing
  const preToolUseResult = await globalHookExecutor.executeHooks(...);
  if (preToolUseResult.preventContinuation) { ... }

  // Execute tool
  try {
    result = await tool.call(finalArgs, {...}); // Sequential execution
  } catch (e) {
    error = e instanceof Error ? e : new Error(String(e));
  }

  // Post hooks
  const postToolUseResult = await globalHookExecutor.executeHooks(...);

  return { blocked: false, result, ... };
}
\`\`\`

**Problem**: When LLM requests multiple independent tools (e.g., read 3 files), they execute sequentially, missing parallelism opportunities

**Proposed solution**: Dependency graph parallel execution
\`\`\`typescript
class ParallelToolExecutor {
  async executeTools(toolCalls: ToolCall[]): Promise<ToolResult[]> {
    const graph = this.buildDependencyGraph(toolCalls);
    const results = new Map<string, ToolResult>();

    for (const batch of graph.topologicalBatches()) {
      const batchResults = await Promise.all(
        batch.map(call => this.executeWithRetry(call))
      );
      // Merge results
      batchResults.forEach(r => results.set(r.id, r.result));
    }

    return [...results.values()];
  }

  private buildDependencyGraph(calls: ToolCall[]): DependencyGraph {
    const graph = new DependencyGraph();

    // Detect dependencies
    for (const call of calls) {
      const deps = this.detectDependencies(call, calls);
      graph.addNode(call.id, deps);
    }

    return graph;
  }
}
