// neuro-memory-batcher.ts (NEW FILE)

type QueuedMemory = {
  content: string;
  metadata: Record<string, unknown>;
  timestamp: number;
};

export class MemoryBatcher {
  private queue: QueuedMemory[] = [];
  private flushTimer?: ReturnType<typeof setTimeout>;
  private isFlushing = false;

  constructor(
    private bridge: NeuroMemoryBridge,
    private options: {
      maxBatchSize: number;     // Flush after N items (e.g., 10)
      maxWaitMs: number;         // Flush after X ms (e.g., 100ms)
    }
  ) {}

  /**
   * Queue a memory for batch storage (non-blocking)
   */
  queueMemory(content: string, metadata: Record<string, unknown>): void {
    this.queue.push({ content, metadata, timestamp: Date.now() });

    // Flush if batch full
    if (this.queue.length >= this.options.maxBatchSize) {
      this.flush();
      return;
    }

    // Otherwise, schedule debounced flush
    this.scheduleFlush();
  }

  /**
   * Schedule debounced flush
   */
  private scheduleFlush(): void {
    if (this.flushTimer) {
      clearTimeout(this.flushTimer);
    }

    this.flushTimer = setTimeout(() => {
      this.flush();
    }, this.options.maxWaitMs);
  }

  /**
   * Flush queue to Python in single batch
   */
  async flush(): Promise<void> {
    if (this.isFlushing || this.queue.length === 0) return;

    this.isFlushing = true;

    // Clear timer
    if (this.flushTimer) {
      clearTimeout(this.flushTimer);
      this.flushTimer = undefined;
    }

    // Take all queued items
    const batch = this.queue.splice(0, this.queue.length);

    try {
      // Send batch to Python (need to add batch endpoint)
      await this.bridge.storeMemoryBatch(batch);
    } catch (error) {
      log.error(`Batch store failed (${batch.length} items):`, error);
      // Items lost on failure - acceptable for memory system
    } finally {
      this.isFlushing = false;

      // If more items queued during flush, schedule again
      if (this.queue.length > 0) {
        this.scheduleFlush();
      }
    }
  }

  /**
   * Force flush (for graceful shutdown)
   */
  async drain(): Promise<void> {
    await this.flush();
  }
}
