/**
 * Stop the neuro-memory-agent MCP server
 */
async stop(): Promise<void> {
  // Flush remaining memories before shutdown
  if (this.memoryBatch) {
    log.info("Flushing remaining memory batch...");
    await this.memoryBatch.shutdown();
  }

  if (this.consolidateTimer) {
    clearInterval(this.consolidateTimer);
  }

  if (this.process) {
    return new Promise((resolve) => {
      this.process!.on("exit", () => {
        log.info("Neuro-memory-agent stopped");
        resolve();
      });
      this.process!.kill("SIGTERM");

      // Force kill after 5s
      setTimeout(() => {
        if (this.process) {
          this.process.kill("SIGKILL");
        }
      }, 5000);
    });
  }
}

/**
 * Initialize batch queue
 */
private initBatchQueue(): void {
  this.memoryBatch = new MemoryBatchQueue({
    batchSize: this.config.batchConfig!.batchSize,
    flushInterval: this.config.batchConfig!.flushInterval,
    maxQueueSize: this.config.batchConfig!.maxQueueSize,
    onFlush: async (items: BatchMemoryItem[]): Promise<BatchStoreResult[]> => {
      return this.batchStoreInternal(items);
    },
  });

  log.info(
    `Memory batching enabled (batch: ${this.config.batchConfig!.batchSize}, ` +
      `interval: ${this.config.batchConfig!.flushInterval}ms)`,
  );
}

