declare const PartitionNameBrand: unique symbol;
type PartitionName = string & { readonly [PartitionNameBrand]: true };

function parsePartitionName(name: string): PartitionName | null {
  const match = name.match(/^agent_events_(\d{4})_(\d{2})$/);
  if (!match) return null;
  return name as PartitionName;
}

function createPartitionName(year: number, month: number): PartitionName {
  return `agent_events_${year}_${String(month).padStart(2, '0')}` as PartitionName;
}
