#### 1.1 SQL Injection Vulnerability
The partition name is concatenated directly into SQL without validation:

```typescript
// CURRENT (VULNERABLE)
this.db.prepare(`CREATE TABLE IF NOT EXISTS ${partitionName} ...`).run();
```

**Fix:**
```typescript
// Validate partition name format strictly
private validatePartitionName(name: string): boolean {
  return /^agent_events_\d{4}_\d{2}$/.test(name);
}

private async createPartitionForDate(date: Date): Promise<void> {
  const partitionName = this.getPartitionName(date.getTime());

  if (!this.validatePartitionName(partitionName)) {
    throw new Error(`Invalid partition name format: ${partitionName}`);
  }
  // ... rest of method
}
```

#### 1.2 Timezone Inconsistency (Critical)

```typescript
// CURRENT - uses local timezone
getPartitionName(timestamp: number): string {
  const date = new Date(timestamp);  // LOCAL timezone!
  const year = date.getFullYear();
  const month = String(date.getMonth() + 1).padStart(2, "0");
  return `agent_events_${year}_${month}`;
}

// MIGRATION - uses UTC!
strftime('%Y-%m', timestamp, 'unixepoch') as month  // UTC!
```

**Fix - Use UTC consistently:**
```typescript
getPartitionName(timestamp: number): string {
  const date = new Date(timestamp);
  const year = date.getUTCFullYear();
  const month = String(date.getUTCMonth() + 1).padStart(2, "0");
  return `agent_events_${year}_${month}`;
}
```

#### 1.3 Batch Migration Bug with LIMIT/OFFSET

The migration uses LIMIT/OFFSET which is unreliable:

```typescript
// CURRENT (BROKEN)
const batch = db.prepare(`
  INSERT INTO ${partitionName}
  SELECT * FROM agent_events
  WHERE timestamp >= ? AND timestamp <= ?
  LIMIT ? OFFSET ?
`).run(startTs, endTs, batchSize, migrated);
```

This fails because OFFSET doesn't work correctly with INSERT...SELECT. Also, if data changes during migration, rows can be skipped or duplicated.

**Fix - Use id-based pagination:**
```typescript
let lastId: string | null = null;
let migrated = 0;

while (migrated < monthData.count) {
  const rows = lastId
    ? db.prepare(`
        SELECT * FROM agent_events
        WHERE timestamp >= ? AND timestamp <= ? AND id > ?
        ORDER BY id
        LIMIT ?
      `).all(startTs, endTs, lastId, batchSize)
    : db.prepare(`
        SELECT * FROM agent_events
        WHERE timestamp >= ? AND timestamp <= ?
        ORDER BY id
        LIMIT ?
      `).all(startTs, endTs, batchSize);

  if (rows.length === 0) break;

  // Insert rows into partition
  const insertStmt = db.prepare(`
    INSERT INTO ${partitionName} (id, type, source, timestamp, data, metadata, created_at)
    VALUES (?, ?, ?, ?, ?, ?, ?)
  `);

  for (const row of rows as any[]) {
    insertStmt.run(
      row.id, row.type, row.source, row.timestamp,
      row.data, row.metadata, row.created_at
    );
  }

  lastId = rows[rows.length - 1].id;
  migrated += rows.length;
}
```

#### 1.4 Transaction Usage Bug

```typescript
// CURRENT (WRONG - not how node:sqlite transactions work)
this.db.transaction(() => {
  this.db.prepare("DROP VIEW IF EXISTS agent_events").run();
  this.db.prepare(`CREATE VIEW agent_events AS ...`).run();
})();
```

**Fix - Proper transaction pattern:**
```typescript
private rebuildView(): void {
  try {
    // Use IMMEDIATE transaction for write safety
    this.db.exec("BEGIN IMMEDIATE");

    this.db.prepare("DROP VIEW IF EXISTS agent_events").run();

    const partitions = Array.from(this.currentPartitions).sort();
    if (partitions.length === 0) {
      this.db.exec("ROLLBACK");
      log.warn("No partitions found, skipping view rebuild");
      return;
    }

    const unionQuery = partitions
      .map((p) => `SELECT * FROM ${p}`)
      .join("\n  UNION ALL\n  ");

    this.db.prepare(`CREATE VIEW agent_events AS\n  ${unionQuery}`).run();

    this.db.exec("COMMIT");
    log.debug(`Rebuilt view with ${partitions.length} partitions`);
  } catch (error) {
    this.db.exec("ROLLBACK");
    log.error("Failed to rebuild view:", error);
    throw error;
  }
}
```

