### 2. MIGRATION STRATEGY SAFETY ISSUES

#### 2.1 No Backup or Rollback

**Missing safety measures:**
```typescript
export async function migrateToPartitions(
  db: DatabaseSync,
  batchSize: number = 10000
): Promise<void> {
  // ❌ No backup!
  // ❌ No pre-flight checks!
  // ❌ No checksum verification!

  // ... migration code ...

  // ❌ Drops original table with no recovery path!
  db.prepare("DROP TABLE agent_events").run();
}
```

**Recommended safe migration:**
```typescript
export interface MigrationResult {
  success: boolean;
  eventsMigrated: number;
  partitionsCreated: string[];
  checksumVerified: boolean;
  rollbackAvailable: boolean;
  error?: string;
}

export async function migrateToPartitions(
  db: DatabaseSync,
  options: {
    batchSize?: number;
    dryRun?: boolean;
    keepBackup?: boolean;
    verifyChecksums?: boolean;
  } = {}
): Promise<MigrationResult> {
  const { batchSize = 10000, dryRun = false, keepBackup = true, verifyChecksums = true } = options;

  log.info(`Starting partition migration (dryRun: ${dryRun})...`);

  // 1. Pre-flight checks
  const legacyTable = db
    .prepare("SELECT name FROM sqlite_master WHERE type='table' AND name='agent_events'")
    .get();

  if (!legacyTable) {
    return { success: true, eventsMigrated: 0, partitionsCreated: [], checksumVerified: true, rollbackAvailable: false };
  }

  // 2. Get counts and checksums BEFORE migration
  const beforeCount = db.prepare("SELECT COUNT(*) as count FROM agent_events").get() as { count: number };
  const beforeChecksum = verifyChecksums 
    ? db.prepare("SELECT SUM(typeof(id) || id || type || source || timestamp) as checksum FROM agent_events").get() as { checksum: string | null }
    : null;

  if (dryRun) {
    log.info(`[DRY RUN] Would migrate ${beforeCount.count} events`);
    return { success: true, eventsMigrated: 0, partitionsCreated: [], checksumVerified: false, rollbackAvailable: false };
  }

  // 3. Create backup table (rename, don't drop)
  log.info("Creating backup of legacy table...");
  db.prepare("DROP TABLE IF EXISTS agent_events_backup").run();
  db.prepare("ALTER TABLE agent_events RENAME TO agent_events_backup").run();

  // ... rest of migration using agent_events_backup as source ...

  // 4. Verify checksums AFTER migration
  let totalMigrated = 0;
  const afterChecksum = verifyChecksums
    ? computeMigratedChecksum(db, partitionsCreated)
    : null;

  const checksumVerified = !verifyChecksums || beforeChecksum?.checksum === afterChecksum;

  // 5. Keep or drop backup based on verification
  if (!checksumVerified) {
    log.error("CHECKSUM MISMATCH! Keeping backup table for manual recovery");
    return {
      success: false,
      eventsMigrated: totalMigrated,
      partitionsCreated,
      checksumVerified: false,
      rollbackAvailable: true,
      error: "Data integrity check failed - backup retained"
    };
  }

  if (!keepBackup) {
    log.info("Dropping backup table...");
    db.prepare("DROP TABLE agent_events_backup").run();
  } else {
    log.info("Backup table retained: agent_events_backup");
  }

  return {
    success: true,
    eventsMigrated: totalMigrated,
    partitionsCreated,
    checksumVerified: true,
    rollbackAvailable: keepBackup
  };
}
```

#### 2.2 No Progress Persistence

If migration crashes, there's no way to resume:

```typescript
// Add progress tracking
interface MigrationProgress {
  startTime: number;
  currentMonth: string | null;
  monthsCompleted: string[];
  eventsMigrated: number;
  status: 'in_progress' | 'completed' | 'failed';
}

private saveProgress(progress: MigrationProgress): void {
  this.db.prepare(`
    INSERT OR REPLACE INTO migration_progress (id, data, updated_at)
    VALUES ('partition_migration', ?, unixepoch())
  `).run(JSON.stringify(progress));
}

private loadProgress(): MigrationProgress | null {
  const row = this.db.prepare(`
    SELECT data FROM migration_progress WHERE id = 'partition_migration'
  `).get() as { data: string } | undefined;

  return row ? JSON.parse(row.data) : null;
}
```

