### 3. PERFORMANCE CONCERNS

#### 3.1 SQLite Doesn't Do Partition Pruning

This is a **critical architectural issue**. SQLite will scan ALL partitions in the UNION ALL view, even for queries filtering by timestamp:

```sql
-- This WILL query ALL partitions, not just the matching one!
SELECT * FROM agent_events 
WHERE timestamp >= 1706745600 AND timestamp < 1709424000;
```

**Workaround - Use direct partition queries for known time ranges:**
```typescript
/**
 * Query events with automatic partition targeting
 */
queryEvents(options: {
  startTime?: number;
  endTime?: number;
  type?: string;
  source?: string;
  limit?: number;
}): AgentEvent[] {
  if (!options.startTime || !options.endTime) {
    // Fall back to full view scan
    return this.queryAllPartitions(options);
  }

  // Target specific partitions based on time range
  const partitions = this.getPartitionsForRange(options.startTime, options.endTime);

  if (partitions.length === 1) {
    // Single partition - direct query
    return this.db.prepare(`
      SELECT * FROM ${partitions[0]}
      WHERE timestamp >= ? AND timestamp < ?
        ${options.type ? 'AND type = ?' : ''}
        ${options.source ? 'AND source = ?' : ''}
      ORDER BY timestamp DESC
      LIMIT ?
    `).all(
      options.startTime, 
      options.endTime,
      ...(options.type ? [options.type] : []),
      ...(options.source ? [options.source] : []),
      options.limit ?? 1000
    ) as AgentEvent[];
  }

  // Multiple partitions - query each and merge
  // ...
}

private getPartitionsForRange(startTime: number, endTime: number): string[] {
  const partitions: string[] = [];
  const start = new Date(startTime);
  const end = new Date(endTime);

  // Handle range spanning multiple months
  let current = new Date(Date.UTC(start.getUTCFullYear(), start.getUTCMonth(), 1));
  while (current <= end) {
    const name = `agent_events_${current.getUTCFullYear()}_${String(current.getUTCMonth() + 1).padStart(2, '0')}`;
    if (this.currentPartitions.has(name)) {
      partitions.push(name);
    }
    current.setUTCMonth(current.getUTCMonth() + 1);
  }

  return partitions;
}
```

#### 3.2 Index Creation Order

Create indexes AFTER data load for faster migration:

```typescript
// WRONG - indexes slow down inserts
db.prepare(`CREATE TABLE ...`).run();
db.prepare(`CREATE INDEX ...`).run();
// Insert 50k rows -> slow!

// RIGHT - bulk load then index
db.prepare(`CREATE TABLE ...`).run();
// Insert 50k rows -> fast!
db.prepare(`CREATE INDEX ...`).run(); // One-time index build
```

#### 3.3 Missing ANALYZE

After creating new partitions, query planner needs stats:

```typescript
private async createPartitionForDate(date: Date): Promise<void> {
  // ... create table and indexes ...

  // Update query planner statistics
  this.db.exec(`ANALYZE ${partitionName}`);
}
```

