### 4. TYPESCRIPT IMPROVEMENTS

#### 4.1 Better Type Safety

```typescript
// Branded type for partition names
export type PartitionName = string & { readonly __brand: unique symbol };

function asPartitionName(name: string): PartitionName | null {
  return /^agent_events_\d{4}_\d{2}$/.test(name) 
    ? (name as PartitionName) 
    : null;
}

// Result types
export interface PartitionOperationResult {
  readonly success: boolean;
  readonly partitionName: PartitionName;
  readonly error?: Error;
}

export interface PartitionStats {
  readonly partitionCount: number;
  readonly partitions: readonly PartitionName[];
  readonly retentionMonths: number;
  readonly totalRows?: number;
  readonly totalSizeBytes?: number;
}
```

#### 4.2 Proper Error Handling

```typescript
// Define error types
export class PartitionError extends Error {
  constructor(
    message: string,
    public readonly code: 'CREATE_FAILED' | 'DROP_FAILED' | 'VIEW_REBUILD_FAILED' | 'INVALID_NAME',
    public readonly partitionName?: string,
    public readonly cause?: unknown
  ) {
    super(message);
    this.name = 'PartitionError';
  }
}

// Use in methods
private async createPartitionForDate(date: Date): Promise<void> {
  const partitionName = this.getPartitionName(date.getTime());
  const validated = asPartitionName(partitionName);

  if (!validated) {
    throw new PartitionError(
      `Invalid partition name: ${partitionName}`,
      'INVALID_NAME',
      partitionName
    );
  }

  try {
    // ... create logic ...
  } catch (error) {
    throw new PartitionError(
      `Failed to create partition: ${partitionName}`,
      'CREATE_FAILED',
      partitionName,
      error
    );
  }
}
```

#### 4.3 Null Safety in persistEvent

```typescript
// CURRENT (will crash if partitionManager is undefined)
const partitionName = this.partitionManager
  ? this.partitionManager.getPartitionName(event.timestamp)
  : "agent_events";

// BETTER
private persistEvent(event: AgentEvent): void {
  if (!this.db) return;

  const partitionName = this.partitionManager?.getPartitionName(event.timestamp);

  if (!partitionName) {
    log.warn("No partition manager, skipping persistence");
    return;
  }

  // Verify partition exists
  if (!this.partitionManager?.hasPartition(partitionName)) {
    // Auto-create or fail?
    log.error(`Partition ${partitionName} does not exist`);
    return;
  }

  // ... insert ...
}
```

