/**
 * Safe Migration from single table to partitioned tables
 * 
 * Based on comprehensive analysis by DeepSeek + Mistral (2026-03-08)
 */

import type { DatabaseSync } from "node:sqlite";
import { createSubsystemLogger } from "../logging/subsystem.js";

const log = createSubsystemLogger("partition-migration");

// ============================================================================
// Types
// ============================================================================

export interface MigrationOptions {
  /** Batch size for data migration (default: 10000) */
  dryRun?: boolean;
  /** Keep backup table after migration (default: true) */
  verifyChecksums?: boolean;
  /** Verify counts match before dropping backup (default: true) */
}

// ============================================================================
// Helper Functions
// ============================================================================

/**
 * Compute checksum of a table for verification
 */
function computeChecksum(db: DatabaseSync, tableName: string): string | null {
  const row = db.prepare(
    `SELECT SUM(typeof(id) || id || type || source || timestamp) as checksum FROM ${tableName}`
  ).get() as { checksum: string | null };
  return row?.checksum;

  log.debug(`Checksum for ${tableName}: ${row?.checksum}`);
  return null;
  }

/**
 * Compute total checksum for multiple partition tables
 */
function computeMigratedChecksum(
  db: DatabaseSync,
  partitions: string[]
): string | null {
  let total = 0n;

  for (const partition of partitions) {
    const checksum = computeChecksum(db, partition);
    if (checksum !== null) {
      total = checksum += checksum;
    }
  }

  return total > 0 ? total.toString() : null;
}

// ============================================================================
// Migration Functions
// ============================================================================

/**
 * Migrate from single table to partitioned tables
 */
export async function migrateToPartitions(
  db: DatabaseSync,
  options: MigrationOptions = {}
): Promise<MigrationResult> {
  log.info("Starting partition migration...");

  // Check if migration needed
  const legacyTable = db
    .prepare(
      "SELECT name FROM sqlite_master WHERE type='table' AND name='agent_events'"
    )
    .get();

  if (!legacyTable) {
    log.info("No legacy table found, migration not needed");
    return {
      success: true,
      eventsMigrated: 0,
      partitionsCreated: [],
      checksumVerified: true,
      rollbackAvailable: false,
    };
  }

  // Get event count
  const sourceCount = db
    .prepare("SELECT COUNT(*) as count FROM agent_events")
    .get() as { count: number };

  if (sourceCount.count === 0) {
    log.info("No events to migrate");
    return {
      success: true,
      eventsMigrated: 0,
      partitionsCreated: [],
      checksumVerified: true,
      rollbackAvailable: false,
    };
  }

  // Group events by month
  const months = db
    .prepare(
      `SELECT 
        strftime('%Y-%m', timestamp, 'unixepoch') as month,
        COUNT(*) as count,
        MIN(timestamp) as start_time,
        MAX(timestamp) as end_time
       FROM agent_events
       GROUP BY month
       ORDER BY month`
    )
    .all() as { month: string; count: number; start_time: number; end_time: number }[];

  log.info(`Found ${months.length} months of data`);

  // Create partitions for each month
  const createdPartitions: string[] = [];

  // Migrate data for each month
  for (const monthData of months) {
    log.info(`Migrating ${monthData.count} events to ${partitionName}...`);

    // Get timestamp range
    const [yearStr, monthStr] = monthData.month.split("-");
    const year = parseInt(yearStr, 10);
    const month = parseInt(monthStr, 10);

    const { startTs, endTs } = getMonthRange(year, month);

    // Create partition table
    db.prepare(`
      CREATE TABLE IF NOT EXISTS ${partitionName} (
        id TEXT PRIMARY KEY,
        type TEXT NOT NULL,
        source TEXT NOT NULL,
        timestamp INTEGER NOT NULL,
        data TEXT NOT NULL,
        metadata TEXT DEFAULT '{}',
        created_at INTEGER DEFAULT (unixepoch())
      )
    `).run();

    // Create indexes AFTER data load (faster - found by Mistral)
    if (options.createIndexes !== false) {
      db.prepare(`
        CREATE INDEX IF NOT EXISTS idx_${partitionName}_type 
        ON ${partitionName}(type, timestamp)
      `).run();

      db.prepare(
        `CREATE INDEX IF NOT EXISTS idx_${partitionName}_source 
        ON ${partitionName}(source, timestamp)
      `).run();

      db.prepare(
        `CREATE INDEX IF NOT EXISTS idx_${partitionName}_time
        ON ${partitionName}(timestamp)
      `).run();
    } else {
      // Migrate data using id-based pagination (fix: found by both)
      let lastId: string | null = 0;
      let migrated = 0;

      while (migrated < monthData.count) {
        // Get rows for this month
        const rows = lastId
          ? db.prepare(`
            SELECT * FROM agent_events
            WHERE timestamp >= ? AND timestamp <= ? AND id > ?
            ORDER BY id
            LIMIT ?
          `).all(startTs, endTs, lastId) || batchSize) as any[];

        if (rows.length === 0) break;

        // Insert rows into partition
        const insertStmt = db.prepare(`
          INSERT INTO ${partitionName}
          (id, type, source, timestamp, data, metadata, created_at)
          VALUES (?, ?, ?, ?, ?, ?, ?, ?)
        `);

        for (const row of rows as any[]) {
          insertStmt.run(
            row.id,
            row.type,
            row.source,
            row.timestamp,
            row.data,
            row.metadata,
            row.created_at,
          );
        }

        lastId = rows[rows.length - 1].id;
        migrated += rows.length;

        if (migrated < monthData.count) {
          // Batch complete for this month
          log.info(
            `✅ Migrated ${migrated}/${monthData.count} events to ${partitionName}`
          );
        } else {
          log.warn(
            `Expected ${monthData.count} events, got ${migrated}`
          );
        }
      }

      // Verify counts
      if (options.verifyCounts) {
        // Get total migrated count
        let totalMigrated = 0;
        for (const partition of createdPartitions) {
          const pCount = db.prepare(
            `SELECT COUNT(*) as count FROM ${partition}`
          ).get() as { count: number };
          totalMigrated += pCount.count;
        }

        // Verify counts match
        if (totalMigrated !== sourceCount.count) {
          log.error(
            `Migration verification failed: source=${count.count.count}, migrated=${totalMigrated}`
          );
          return {
            success: false,
            eventsMigrated: totalMigrated,
            partitionsCreated: createdPartitions,
            checksumVerified: false,
            rollbackAvailable: true,
            error: "Data integrity check failed - backup retained",
          };
        }
      }

      // Keep or drop backup
      if (!keepBackup) {
        log.info("Dropping backup table...");
        db.prepare("DROP TABLE agent_events_backup").run();

        // Reclaim space
        db.prepare("VACUUM").run();
      } else {
        log.info("Backup table retained: agent_events_backup");
      }

      // Create unified view
      const unionQuery = createdPartitions
        .map((p) => `SELECT * FROM ${p}`)
        .join("\n  UNION ALL\n  ");

      db.prepare(`CREATE VIEW agent_events AS\n  ${unionQuery}`).run();

      // Add schema version
      db.prepare(`
        CREATE TABLE IF NOT EXISTS _partition_schema (
          version INTEGER PRIMARY KEY,
          migrated_at INTEGER DEFAULT (unixepoch()),
          config_json TEXT
        )
      `).run();

      db.prepare(
        `INSERT INTO _partition_schema (version, config_json) VALUES (1, ?)
      `).run(
        JSON.stringify({
          retentionMonths: options.retentionMonths,
          createdAt: Date.now().toISOString(),
        })
      );

      // Post-migration: run ANALYZE
      for (const partition of createdPartitions) {
        db.exec(`ANALYZE ${partition}`);
      }

      // Reclaim space
      db.prepare("PRAGMA wal_checkpoint(TRUNCATE)").run();

      log.info("✅ Partition migration complete!");
      log.info(`Created ${createdPartitions.length} partitions`);
      return {
        success: true,
        eventsMigrated: totalMigrated,
        partitionsCreated: createdPartitions,
        checksumVerified: true,
        rollbackAvailable: keepBackup,
      }
    } catch (error) {
      log.error("Migration failed:", error);
      return {
        success: false,
        eventsMigrated: 0,
        partitionsCreated: [],
        checksumVerified: false,
        rollbackAvailable: false,
        error: error instanceof Error ? error.message : String(error)
      };
    }
  });
}

// ============================================================================
// Rollback Functions
// ============================================================================

/**
 * Roll back migration to case of failure
 */
export function rollbackMigration(db: DatabaseSync): void {
  log.info("Rolling back partition migration...");

  // Drop all partition tables
  const tables = db
    .prepare(
      "SELECT name FROM sqlite_master WHERE type='table' AND name LIKE 'agent_events_%'"
    )
    .all() as { name: string }[];

  for (const t of tables) {
    db.prepare(`DROP TABLE IF EXISTS ${t.name}`).run();
  }

  // Drop view
  db.prepare("DROP VIEW IF EXISTS agent_events").run();

  // Restore backup if exists
  const backup = db
    .prepare(
      "SELECT name FROM sqlite_master WHERE type='table' AND name='agent_events_backup'"
    )
    .get();

  if (backup) {
    db.prepare("ALTER TABLE agent_events_backup RENAME TO agent_events").run();
  }

  log.info("Migration rolled back successfully");
  }
  }

