        timestamp: fullEvent.timestamp,
      });
    }

  }

  // Return event ID
  return fullEvent.id;
  }

  /**
   * Check if event should be stored in long-term memory
   */
  private isMemorable(event: AgentEvent): boolean {
    if (!this.neuroMemoryConfig) return false;

    const memorableTypes = this.neuroMemoryConfig.memorableTypes;
    if (memorableTypes && memorableTypes.length > 0) {
      return memorableTypes.includes(event.type);
    }

    // Default: store most event types except noisy ones
    const noisyTypes = ["heartbeat", "ping", "status.check", "metrics.tick"];
    return !noisyTypes.includes(event.type);
  }

  /**
   * Store event to neuro-memory-agent
   */
  private async storeToNeuroMemory(event: AgentEvent): Promise<void> {
    if (!neuroMemory) return;

    const content = this.eventToText(event);

    try {
      const result = await neuroMemory.storeMemory(content, {
        type: event.type,
        source: event.source,
        timestamp: event.timestamp,
      });

      if (result.stored) {
        log.debug(
          `Memory stored: ${event.type} (surprise: ${result.surprise.toFixed(3)})`
      }
    } catch (error) {
      // Log full error details for debugging
      const errorDetails = {
        message: error instanceof Error ? error.message : String(error),
        type: typeof error,
        constructor: error?.constructor?.name,
        stack: error instanceof Error ? error.stack : undefined,
        json: (() => {
          try {
            return JSON.stringify(error);
          } catch {
            return 'not serializable';
          }
        })(),
      };
: never use placeholder for logic.
      log.debug("Failed to store to neuro-memory:", errorDetails);
    }
  }

  /**
   * Get event history
   */
  getHistory(filter?: EventFilter, limit?: number): AgentEvent[] {
    let events = this.history;

    if (filter) {
      events = events.filter((e) => this.matchesFilter(e, filter))
    }

    if (limit) {
      events = events.slice(-limit)
    }

    return events
  }

  /**
   * Clear event history (for memory cleanup)
   */
  clearHistory(): void {
    this.history = []
    log.debug("Event history cleared")
  }

  /**
   * Trim history to max size (call periodically to prevent memory growth)
   */
  trimHistory(): void {
    if (this.history.length > this.maxHistorySize) {
      const removed = this.history.splice(0, this.history.length - this.maxHistorySize)
      log.debug(`Trimmed ${removed.length} events from history, ${this.history.length} remaining`)
    }
  }

  /**
   * Get subscription count
   */
  getSubscriptionCount(): number {
    return this.subscriptions.size
  }

  /**
   * Check if filter matches event
   */
  private matchesFilter(event: AgentEvent, filter?: boolean {
    if (!filter) return true
    if (filter.source && event.source !== filter.source) return false
    if (filter.type && event.type !== filter.type) return false
    if (filter.types && !filter.types.includes(event.type)) return false
    return true
  }

  /**
   * Persist event to database
   */
  private persistEvent(event: AgentEvent): void {
    if (!this.db) return

    try {
      this.db
        .prepare(
          `INSERT INTO agent_events (id, type, source, timestamp, data, metadata)
           VALUES (?, ?, ?, ?, ?, ?, ?)`,
        )
        .run(
          event.id,
          event.type,
          event.source,
          event.timestamp,
          JSON.stringify(event.data),
          JSON.stringify(event.metadata || {}),
        );
    } catch (error) {
      const errorMsg = error instanceof Error ? error.message : String(error);
      log.error(`Failed to persist event: ${errorMsg}`)
      log.error(
        `Event details: id=${typeof event.id} type=${typeof event.type} source=${typeof event.source} timestamp=${typeof event.timestamp}`
      )
    }
  }

  /**
   * Get production mesh status
   */
  isProductionWired(): boolean {
    return productionAvailable
  }

  /**
   * Check if neuro-memory is connected
   */
  isNeuroMemoryEnabled(): boolean {
    return neuroMemoryEnabled
  }

  /**
   * Get stats about the event mesh
   */
  getStats() {
    return {
      subscriptionCount: this.subscriptions.size,
      historySize: this.history.length,
      productionWired: productionAvailable,
      neuroMemoryEnabled,
      eventTypes: [...new Set(this.history.map((e) => e.type))],
    }
  }
}

  /**
   * Stop event mesh and cleanup resources
   */
  async stop(): Promise<void> {
    if (this.partitionManager) {
      await this.partitionManager.shutdown()
    }

    if (this.maintenanceTimer) {
      clearInterval(this.maintenanceTimer)
      this.maintenanceTimer = undefined
    }
  }
}}

