/**
 * Event Mesh - Event Bus with Persistence
 *
 * Features:
 * - Event publishing and subscription
 * - In-memory history buffer
 * - SQLite persistence (optional)
 * - Neuro-memory integration
 * - Partition-based storage (automatic routing)
 */

import type { DatabaseSync } from "node:sqlite";
import { randomUUID } from "node:crypto";
import { createSubsystemLogger } from "../logging/subsystem.js";
import { EventPartitionManager, migrateToPartitions } from "../infra/event-partition-manager.js";

const log = createSubsystemLogger("event-mesh");

// ============================================================================
// Types
// ============================================================================

export type AgentEvent = {
  id: string;
  type: string;
  source: string;
  timestamp: number;
  data: any;
  metadata?: Record<string, any>;
  created_at?: number;
};

export type EventFilter = {
  type?: string;
  source?: string;
  startTime?: number;
  endTime?: number;
};

export type EventMeshConfig = {
  agentId: string;
  db?: DatabaseSync | null;
  enablePersistence?: boolean;
  maxListeners?: number;
  neuroMemory?: {
    enabled: boolean;
    agentPath?: string;
    memorableTypes?: string[];
    surpriseThreshold?: number;
  };
  partitioning?: {
    enabled?: boolean;
    retentionMonths?: number;
    createAheadMonths?: number;
    maintenanceIntervalMs?: number;
  };
};

export type EventTypes = string;

// ============================================================================
// Global Registry (Singleton)
// ============================================================================

export const globalEventMeshRegistry = new Map<string, AgentEventMesh>();

/**
 * Get or create global event mesh instance
 */
export function getEventMesh(config: EventMeshConfig): AgentEventMesh {
  const key = config.agentId;

  if (!globalEventMeshRegistry.has(key)) {
    const mesh = new AgentEventMesh(config);
    globalEventMeshRegistry.set(key, mesh);
  }

  return globalEventMeshRegistry.get(key)!;
}

/**
 * Get or create singleton event mesh
 */
export function getOrCreateEventMesh(config: EventMeshConfig): AgentEventMesh {
  return getEventMesh(config);
}

// ============================================================================
// AgentEventMesh Class
// ============================================================================

export class AgentEventMesh {
  private readonly agentId: string;
  private readonly db: DatabaseSync | null;
  private readonly enablePersistence: boolean;
  private readonly maxHistorySize: number;
  private readonly history: AgentEvent[] = [];
  private readonly subscribers: Map<string, Set<(event: AgentEvent) => void>> = new Map();
  private readonly allEventSubscribers: Set<(event: AgentEvent) => void> = new Set();
  private partitionManager?: EventPartitionManager;
  private isInitialized = false;

  constructor(config: EventMeshConfig) {
    this.agentId = config.agentId;
    this.db = config.db ?? null;
    this.enablePersistence = config.enablePersistence ?? false;
    this.maxHistorySize = 100;

    // Initialize partition manager if persistence and partitioning enabled
    if (this.db && this.enablePersistence && config.partitioning?.enabled !== false) {
      this.partitionManager = new EventPartitionManager(this.db, {
        retentionMonths: config.partitioning?.retentionMonths ?? 12,
        createAheadMonths: config.partitioning?.createAheadMonths ?? 1,
        maintenanceIntervalMs: config.partitioning?.maintenanceIntervalMs ?? 3600000,
      });
    }
  }

  /**
   * Initialize event mesh (async setup)
   */
  async initialize(): Promise<void> {
    if (this.isInitialized) return;

    // Initialize partition manager
    if (this.partitionManager) {
      await this.partitionManager.initialize();
      log.debug("Partition manager initialized");
    }

    // Create legacy table if partitioning disabled
    if (this.db && this.enablePersistence && !this.partitionManager) {
      this.db.exec(`
        CREATE TABLE IF NOT EXISTS agent_events (
          id TEXT PRIMARY KEY,
          type TEXT NOT NULL,
          source TEXT NOT NULL,
          timestamp INTEGER NOT NULL,
          data TEXT NOT NULL,
          metadata TEXT DEFAULT '{}',
          created_at INTEGER DEFAULT (unixepoch())
        )
      `);

      this.db.exec(`
        CREATE INDEX IF NOT EXISTS idx_events_type 
        ON agent_events(type, timestamp)
      `);

      this.db.exec(`
        CREATE INDEX IF NOT EXISTS idx_events_source 
        ON agent_events(source, timestamp)
      `);
    }

    this.isInitialized = true;
    log.debug("Event mesh initialized");
  }

  /**
   * Publish an event
   */
  async publish(type: string, data: any, metadata?: Record<string, any>): Promise<string> {
    const event: AgentEvent = {
      id: randomUUID(),
      type,
      source: this.agentId,
      timestamp: Date.now(),
      data,
      metadata,
    };

    // Add to in-memory history
    this.history.push(event);
    if (this.history.length > this.maxHistorySize) {
      this.history.shift();
    }

    // Persist to SQLite
    if (this.db && this.enablePersistence) {
      await this.persistEvent(event);
    }

    // Emit to subscribers
    this.emit(event);

    return event.id;
  }

  /**
   * Persist event to SQLite
   *
   * CRITICAL: Routes to correct partition (fixes race condition found by DeepSeek)
   */
  private async persistEvent(event: AgentEvent): Promise<void> {
    if (!this.db) return;

    try {
      // Use partition manager if available
      if (this.partitionManager) {
        // Ensure partition exists for this event's timestamp
        const partitionName = await this.partitionManager.ensurePartitionExists(event.timestamp);

        // Insert into partition
        this.db
          .prepare(
            `INSERT INTO ${partitionName} 
            (id, type, source, timestamp, data, metadata, created_at) 
            VALUES (?, ?, ?, ?, ?, ?, ?)`
          )
          .run(
            event.id,
            event.type,
            event.source,
            Math.floor(event.timestamp / 1000), // Convert to Unix seconds
            JSON.stringify(event.data),
            JSON.stringify(event.metadata ?? {}),
            Math.floor(Date.now() / 1000)
          );
      } else {
        // Fallback to legacy table
        this.db
          .prepare(
            `INSERT INTO agent_events 
            (id, type, source, timestamp, data, metadata, created_at) 
            VALUES (?, ?, ?, ?, ?, ?, ?)`
          )
          .run(
            event.id,
            event.type,
            event.source,
            Math.floor(event.timestamp / 1000),
            JSON.stringify(event.data),
            JSON.stringify(event.metadata ?? {}),
            Math.floor(Date.now() / 1000)
          );
      }
    } catch (error) {
      log.error("Failed to persist event:", error);
    }
  }

  /**
   * Subscribe to specific event type
   */
  subscribe(
    type: string,
    handler: (event: AgentEvent) => void,
    filter?: EventFilter
  ): () => void {
    if (!this.subscribers.has(type)) {
      this.subscribers.set(type, new Set());
    }

    const wrappedHandler = filter
      ? (event: AgentEvent) => {
          if (this.matchesFilter(event, filter)) {
            handler(event);
          }
        }
      : handler;

    this.subscribers.get(type)!.add(wrappedHandler);

    // Return unsubscribe function
    return () => {
      this.subscribers.get(type)?.delete(wrappedHandler);
    };
  }

  /**
   * Subscribe to all events
   */
  subscribeAll(handler: (event: AgentEvent) => void): () => void {
    this.allEventSubscribers.add(handler);
    return () => {
      this.allEventSubscribers.delete(handler);
    };
  }

  /**
   * Emit event to subscribers
   */
  private emit(event: AgentEvent): void {
    // Notify type-specific subscribers
    const handlers = this.subscribers.get(event.type);
    if (handlers) {
      for (const handler of handlers) {
        try {
          handler(event);
        } catch (error) {
          log.error(`Error in event handler for ${event.type}:`, error);
        }
      }
    }

    // Notify all-event subscribers
    for (const handler of this.allEventSubscribers) {
      try {
        handler(event);
      } catch (error) {
        log.error("Error in all-event handler:", error);
      }
    }
  }

  /**
   * Query events from persistence layer
   *
   * PERFORMANCE: Uses partition-aware queries (found by both)
   */
  queryEvents(filter: EventFilter & { limit?: number }): AgentEvent[] {
    if (!this.db || !this.enablePersistence) {
      // Fall back to in-memory history
      return this.filterHistory(filter);
    }

    try {
      // Use partition manager for time-range queries
      if (this.partitionManager && filter.startTime && filter.endTime) {
        const rows = this.partitionManager.queryEvents({
          startTime: filter.startTime,
          endTime: filter.endTime,
          type: filter.type,
          source: filter.source,
          limit: filter.limit ?? 1000,
        });

        return rows.map((row: any) => this.rowToEvent(row));
      }

      // Fall back to direct query (legacy or no time range)
      let query = "SELECT * FROM agent_events WHERE 1=1";
      const params: any[] = [];

      if (filter.type) {
        query += " AND type = ?";
        params.push(filter.type);
      }

      if (filter.source) {
        query += " AND source = ?";
        params.push(filter.source);
      }

      if (filter.startTime) {
        query += " AND timestamp >= ?";
        params.push(Math.floor(filter.startTime / 1000));
      }

      if (filter.endTime) {
        query += " AND timestamp < ?";
        params.push(Math.floor(filter.endTime / 1000));
      }

      query += " ORDER BY timestamp DESC LIMIT ?";
      params.push(filter.limit ?? 1000);

      const rows = this.db.prepare(query).all(...params) as any[];
      return rows.map((row) => this.rowToEvent(row));
    } catch (error) {
      log.error("Failed to query events:", error);
      return [];
    }
  }

  /**
   * Convert database row to AgentEvent
   */
  private rowToEvent(row: any): AgentEvent {
    return {
      id: row.id,
      type: row.type,
      source: row.source,
      timestamp: row.timestamp * 1000, // Convert to milliseconds
      data: JSON.parse(row.data),
      metadata: row.metadata ? JSON.parse(row.metadata) : undefined,
      created_at: row.created_at,
    };
  }

  /**
   * Filter in-memory history
   */
  private filterHistory(filter: EventFilter & { limit?: number }): AgentEvent[] {
    let results = this.history.filter((event) => this.matchesFilter(event, filter));

    // Sort by timestamp descending
    results.sort((a, b) => b.timestamp - a.timestamp);

    // Apply limit
    if (filter.limit) {
      results = results.slice(0, filter.limit);
    }

    return results;
  }

  /**
   * Check if event matches filter
   */
  private matchesFilter(event: AgentEvent, filter: EventFilter): boolean {
    if (filter.type && event.type !== filter.type) return false;
    if (filter.source && event.source !== filter.source) return false;
    if (filter.startTime && event.timestamp < filter.startTime) return false;
    if (filter.endTime && event.timestamp >= filter.endTime) return false;
    return true;
  }

  /**
   * Get in-memory history
   */
  getHistory(): AgentEvent[] {
    return [...this.history];
  }

  /**
   * Get partition stats
   */
  getPartitionStats() {
    return this.partitionManager?.getStats() ?? null;
  }

  /**
   * Close event mesh
   */
  close(): void {
    // Remove from global registry
    globalEventMeshRegistry.delete(this.agentId);

    // Shutdown partition manager
    if (this.partitionManager) {
      this.partitionManager.shutdown();
    }

    // Clear subscribers
    this.subscribers.clear();
    this.allEventSubscribers.clear();

    log.debug("Event mesh closed");
  }

  /**
   * Run migration to partitioned storage
   */
  async migrateToPartitions(): Promise<void> {
    if (!this.db) {
      throw new Error("Database not available");
    }

    const result = await migrateToPartitions(this.db, {
      dryRun: false,
      keepBackup: true,
      verifyChecksums: true,
    });

    if (!result.success) {
      throw new Error(`Migration failed: ${result.error}`);
    }

    log.info(`Migration complete: ${result.eventsMigrated} events migrated to ${result.partitionsCreated.length} partitions`);
  }
}

