(() => {
  // Find the compose box
  const textbox = document.querySelector('[data-testid="tweetTextarea_0"]');
  if (!textbox) return 'Compose box not found';

  // Click to focus
  textbox.focus();
  textbox.click();

  // Set value
  const text = 'Building an AI startup in 2026:\n\nThe tools are democratized (GPT, Claude, Gemini).\nThe infrastructure is accessible.\n\nWhat matters? Domain expertise + understanding user needs.\n\nExecution is everything.\n\n#BuildInPublic #AIStartup';

  // React requires this pattern to detect changes
  const nativeInputValueSetter = Object.getOwnPropertyDescriptor(window.HTMLTextAreaElement.prototype, 'value').set;
  nativeInputValueSetter.call(textbox, text);

  // Trigger events
  textbox.dispatchEvent(new Event('input', { bubbles: true }));
  textbox.dispatchEvent(new Event('change', { bubbles: true }));

  return 'Text injected successfully';
})()

